WITH sales_agg AS ( SELECT cp.cp_department AS department, cp.cp_catalog_page_number AS page_number, sum(cs.cs_net_paid_inc_ship) AS total_sales, sum(cs.cs_net_profit) AS total_profit, avg(cs.cs_ext_discount_amt) AS avg_discount, count(DISTINCT cb.c_customer_id) AS distinct_bill_customers, count(DISTINCT cs_ship.c_customer_id) AS distinct_ship_customers, sum(cs.cs_quantity) AS total_quantity FROM catalog_sales cs JOIN catalog_page cp ON cs.cs_catalog_page_sk = cp.cp_catalog_page_sk JOIN customer cb ON cs.cs_bill_customer_sk = cb.c_customer_sk JOIN customer cs_ship ON cs.cs_ship_customer_sk = cs_ship.c_customer_sk WHERE cp.cp_catalog_number = 3 AND cp.cp_end_date_sk BETWEEN 2450844 AND 2451087 AND cs.cs_quantity > 0 GROUP BY cp.cp_department, cp.cp_catalog_page_number ) SELECT department, page_number, total_sales, total_profit, avg_discount, distinct_bill_customers, distinct_ship_customers, total_quantity, rank() OVER (ORDER BY total_profit DESC) AS profit_rank FROM sales_agg ORDER BY profit_rank LIMIT 5
